use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = mill.stock.planks();
    var result = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let plank = planks[i];
        if mill.rules.keep(plank) {
            let label = mill.rules.label(plank);
            if first {
                result = label;
                first = false;
            } else {
                result = result.concat(other: ",").concat(other: label);
            }
        }
        i = i + 1;
    }
    result
}

use harbor.signal;

fn entries() -> String {
    var result = "";
    var first = true;
    for s in signal.signals() {
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(word) => "fog:".concat(other: word),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
    }
    result
}

