use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    while i < board.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        galley.kitchen.serve(board[i])?;
        i = i + 1;
    }
    return Ok(unit);
}

