use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames()?;
    var total = 0;
    for frame in frames {
        let value = match relay.feed.decode(frame) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + value;
    }
    relay.feed.emit(total: total, io: io)?;
    return Ok(unit);
}

