use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = stable.herd.lineup();
    var result = "";
    var first = true;

    for pony in ponies {
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        let entry = stable.ledger.entry(pony: fed);
        if first {
            result = entry;
            first = false;
        } else {
            result = result.concat(other: ",").concat(other: entry);
        }
    }

    io.write(text: result)?;
    return Ok(unit);
}

